**Plan**
- A list of checkpoint Transforms is watched every frame; the first time the player gets within the activation radius of a later checkpoint it becomes the respawn point, is tinted green and saved in PlayerPrefs.
- `Die()` (called by falling below a kill height, by pressing K, or by any other script) teleports the player to the active checkpoint or the start position and zeroes any Rigidbody velocity.
- The CharacterController is disabled around the teleport (the standard way to move one) and a UI Toolkit toast announces each checkpoint.

```csharp
using System;
using UnityEngine;
using UnityEngine.UIElements;

public class CheckpointRespawn : MonoBehaviour
{
    private const string SaveKey = "Checkpoint.Index";

    [SerializeField] private Transform[] checkpoints;
    [SerializeField] private float activateRadius = 2.5f;
    [SerializeField] private float killHeight = -20f;
    [SerializeField] private KeyCode killKey = KeyCode.K;
    [SerializeField] private Color inactiveColor = new Color(0.8f, 0.3f, 0.2f);
    [SerializeField] private Color activeColor = new Color(0.2f, 0.9f, 0.4f);

    private int current = -1;
    private Vector3 startPosition;
    private CharacterController controller;
    private Rigidbody body;
    private Label toast;

    public event Action OnRespawned;

    private void Start()
    {
        startPosition = transform.position;
        controller = GetComponent<CharacterController>();
        body = GetComponent<Rigidbody>();
        BuildToast();
        current = Mathf.Clamp(PlayerPrefs.GetInt(SaveKey, -1), -1, checkpoints.Length - 1);
        for (int i = 0; i < checkpoints.Length; i++) Paint(i, i <= current);
        if (current >= 0) Respawn();
    }

    private void Update()
    {
        for (int i = current + 1; i < checkpoints.Length; i++)
        {
            Vector3 offset = checkpoints[i].position - transform.position;
            offset.y = 0f;
            if (offset.magnitude <= activateRadius) Activate(i);
        }
        if (transform.position.y < killHeight || Input.GetKeyDown(killKey)) Die();
    }

    public void Die()
    {
        Respawn();
    }

    public void ResetProgress()
    {
        PlayerPrefs.DeleteKey(SaveKey);
        current = -1;
        for (int i = 0; i < checkpoints.Length; i++) Paint(i, false);
    }

    private void Activate(int index)
    {
        current = index;
        PlayerPrefs.SetInt(SaveKey, index);
        PlayerPrefs.Save();
        Paint(index, true);
        toast.text = "Checkpoint " + (index + 1) + " reached";
        toast.style.display = DisplayStyle.Flex;
        toast.schedule.Execute(() => toast.style.display = DisplayStyle.None).StartingIn(2000);
    }

    private void Respawn()
    {
        Vector3 target = current >= 0 ? checkpoints[current].position + Vector3.up * 1.5f : startPosition;
        if (controller != null) controller.enabled = false;
        transform.position = target;
        if (controller != null) controller.enabled = true;
        if (body != null)
        {
            body.velocity = Vector3.zero;
            body.angularVelocity = Vector3.zero;
        }
        if (OnRespawned != null) OnRespawned();
    }

    private void Paint(int index, bool active)
    {
        Renderer r = checkpoints[index].GetComponent<Renderer>();
        if (r != null) r.material.color = active ? activeColor : inactiveColor;
    }

    private void BuildToast()
    {
        UIDocument doc = gameObject.AddComponent<UIDocument>();
        PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
        settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
        settings.referenceResolution = new Vector2Int(1920, 1080);
        doc.panelSettings = settings;
        VisualElement root = doc.rootVisualElement;
        root.pickingMode = PickingMode.Ignore;
        toast = new Label();
        toast.style.position = Position.Absolute;
        toast.style.top = 60;
        toast.style.alignSelf = Align.Center;
        toast.style.fontSize = 36;
        toast.style.color = new Color(0.4f, 1f, 0.6f);
        toast.style.display = DisplayStyle.None;
        root.Add(toast);
    }
}
```

Attach it to the player (with a CharacterController or Rigidbody) and drag the checkpoint objects into the array in order. Only checkpoints further along than the current one can be activated, so walking back never moves your respawn point backwards, and the index is stored in PlayerPrefs so progress survives a restart. Any other script can call `Die()` when health reaches zero.

**Plan**
- `MovingPlatform` (execution order -100 so it updates first) moves between its start and `start + travel` with a short pause at each end and records how far it moved this frame in `FrameDelta`.
- At startup it adds a `PlatformRider` component to every CharacterController in the scene; the rider sphere-casts downward from the controller and, when it finds a platform beneath, calls `controller.Move(platform.FrameDelta)`.
- Because the delta is applied the same frame the platform moves, the player rides it with no sliding or jitter, including on vertical platforms, and it works with any controller script.

```csharp
using UnityEngine;

[DefaultExecutionOrder(-100)]
public class MovingPlatform : MonoBehaviour
{
    [SerializeField] private Vector3 travel = new Vector3(0f, 0f, 10f);
    [SerializeField] private float speed = 3f;
    [SerializeField] private float pauseTime = 0.5f;

    private Vector3 start;
    private Vector3 end;
    private bool towardsEnd = true;
    private float pauseLeft;

    public Vector3 FrameDelta { get; private set; }

    private void Start()
    {
        start = transform.position;
        end = start + travel;
        foreach (CharacterController controller in FindObjectsOfType<CharacterController>())
        {
            if (controller.GetComponent<PlatformRider>() == null) controller.gameObject.AddComponent<PlatformRider>();
        }
    }

    private void Update()
    {
        Vector3 before = transform.position;
        if (pauseLeft > 0f)
        {
            pauseLeft -= Time.deltaTime;
        }
        else
        {
            Vector3 target = towardsEnd ? end : start;
            transform.position = Vector3.MoveTowards(before, target, speed * Time.deltaTime);
            if (transform.position == target)
            {
                towardsEnd = !towardsEnd;
                pauseLeft = pauseTime;
            }
        }
        FrameDelta = transform.position - before;
    }

    private void OnDrawGizmosSelected()
    {
        Vector3 origin = Application.isPlaying ? start : transform.position;
        Gizmos.color = Color.cyan;
        Gizmos.DrawLine(origin, origin + travel);
    }
}

// Added automatically by MovingPlatform to every CharacterController, so you only attach MovingPlatform in the editor.
[DefaultExecutionOrder(0)]
public class PlatformRider : MonoBehaviour
{
    private CharacterController controller;

    private void Awake()
    {
        controller = GetComponent<CharacterController>();
    }

    private void Update()
    {
        Bounds bounds = controller.bounds;
        float radius = controller.radius * 0.9f;
        float distance = bounds.extents.y - radius + 0.25f;
        RaycastHit hit;
        if (!Physics.SphereCast(bounds.center, radius, Vector3.down, out hit, distance, ~0, QueryTriggerInteraction.Ignore)) return;

        MovingPlatform platform = hit.collider.GetComponentInParent<MovingPlatform>();
        if (platform != null && platform.FrameDelta != Vector3.zero) controller.Move(platform.FrameDelta);
    }
}
```

A CharacterController ignores physics parenting, so the platform has to hand it its own movement. Running the platform first (negative execution order) guarantees `FrameDelta` is for the current frame when the rider reads it, and the sphere cast is slightly narrower than the capsule so the player is still carried when standing near an edge. Put a collider on the platform object and tag nothing: any controller standing on it is moved.

**Plan**
- The script sits on the door (which needs a solid collider) and spawns a gold key sphere at a configurable offset; the player (tag `Player`, or the main camera if none) collects it by walking within the pickup radius.
- When the player has the key and comes within the open radius, the door slides up by `openOffset` and stays open; without the key it stays closed and a UI Toolkit message says it is locked.
- The message is throttled so it does not flicker, and the key and door state are both public for save systems.

```csharp
using UnityEngine;
using UnityEngine.UIElements;

public class KeyDoor : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private Vector3 keyOffset = new Vector3(0f, 1f, -8f);
    [SerializeField] private Vector3 openOffset = new Vector3(0f, 4f, 0f);
    [SerializeField] private float openSpeed = 3f;
    [SerializeField] private float pickupRadius = 1.5f;
    [SerializeField] private float openRadius = 3f;

    private GameObject key;
    private Vector3 closedPosition;
    private Label message;
    private float nextLockedMessage;

    public bool HasKey { get; private set; }
    public bool IsOpen { get; private set; }

    private void Start()
    {
        if (player == null)
        {
            GameObject tagged = GameObject.FindWithTag("Player");
            if (tagged != null) player = tagged.transform;
            else if (Camera.main != null) player = Camera.main.transform;
        }
        closedPosition = transform.position;
        key = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        key.name = "DoorKey";
        key.transform.position = transform.position + keyOffset;
        key.transform.localScale = Vector3.one * 0.5f;
        key.GetComponent<Renderer>().material.color = new Color(1f, 0.82f, 0.1f);
        Destroy(key.GetComponent<Collider>());
        BuildMessage();
    }

    private void Update()
    {
        if (player == null) return;

        if (key != null)
        {
            key.transform.Rotate(0f, 120f * Time.deltaTime, 0f);
            if (Vector3.Distance(player.position, key.transform.position) <= pickupRadius)
            {
                HasKey = true;
                Destroy(key);
                Show("Picked up the key!");
            }
        }

        float distance = Vector3.Distance(player.position, closedPosition);
        if (!IsOpen && distance <= openRadius)
        {
            if (HasKey)
            {
                IsOpen = true;
            }
            else if (Time.time >= nextLockedMessage)
            {
                nextLockedMessage = Time.time + 2.5f;
                Show("The door is locked. Find the key.");
            }
        }

        Vector3 target = IsOpen ? closedPosition + openOffset : closedPosition;
        transform.position = Vector3.MoveTowards(transform.position, target, openSpeed * Time.deltaTime);
    }

    private void Show(string text)
    {
        message.text = text;
        message.style.display = DisplayStyle.Flex;
        message.schedule.Execute(() => message.style.display = DisplayStyle.None).StartingIn(2000);
    }

    private void BuildMessage()
    {
        UIDocument doc = gameObject.AddComponent<UIDocument>();
        PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
        settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
        settings.referenceResolution = new Vector2Int(1920, 1080);
        doc.panelSettings = settings;
        doc.rootVisualElement.pickingMode = PickingMode.Ignore;
        message = new Label();
        message.style.position = Position.Absolute;
        message.style.bottom = 120;
        message.style.alignSelf = Align.Center;
        message.style.fontSize = 34;
        message.style.color = Color.white;
        message.style.display = DisplayStyle.None;
        doc.rootVisualElement.Add(message);
    }
}
```

The door stays solid and in place until `HasKey` is true and the player is near it, so approaching without the key just produces the locked message, and the open state is permanent. Putting the whole key-and-door logic in one component avoids needing a separate inventory class; other scripts can read `HasKey` or `IsOpen` if you want to save them.

**Plan**
- `PlatePuzzleGate` sits on the gate and creates three pressure plates at configurable offsets.
- Every frame each plate runs an `OverlapBox` just above its surface; any non-trigger collider (player, crate, anything) on it counts as pressing, so plates only stay down while weight is on them.
- The gate rises only while all three plates are pressed at the same time and drops again when any one is released; a UI Toolkit label shows `Plates: n/3`.

```csharp
using UnityEngine;
using UnityEngine.UIElements;

public class PlatePuzzleGate : MonoBehaviour
{
    [SerializeField] private Vector3[] plateOffsets =
    {
        new Vector3(-4f, -0.4f, -6f), new Vector3(0f, -0.4f, -9f), new Vector3(4f, -0.4f, -6f),
    };
    [SerializeField] private Vector3 plateSize = new Vector3(2f, 0.2f, 2f);
    [SerializeField] private Vector3 openOffset = new Vector3(0f, 5f, 0f);
    [SerializeField] private float openSpeed = 4f;

    private Transform[] plates;
    private Vector3[] platePositions;
    private bool[] pressed;
    private Vector3 closedPosition;
    private Label status;

    public bool AllPressed { get; private set; }

    private void Start()
    {
        closedPosition = transform.position;
        plates = new Transform[plateOffsets.Length];
        platePositions = new Vector3[plateOffsets.Length];
        pressed = new bool[plateOffsets.Length];
        for (int i = 0; i < plates.Length; i++)
        {
            GameObject plate = GameObject.CreatePrimitive(PrimitiveType.Cube);
            plate.name = "Plate " + (i + 1);
            plate.transform.localScale = plateSize;
            platePositions[i] = closedPosition + plateOffsets[i];
            plate.transform.position = platePositions[i];
            plates[i] = plate.transform;
        }
        BuildLabel();
    }

    private void Update()
    {
        int count = 0;
        for (int i = 0; i < plates.Length; i++)
        {
            Vector3 center = platePositions[i] + Vector3.up * (plateSize.y / 2f + 0.2f);
            Vector3 half = new Vector3(plateSize.x * 0.45f, 0.2f, plateSize.z * 0.45f);
            pressed[i] = false;
            foreach (Collider c in Physics.OverlapBox(center, half, Quaternion.identity, ~0, QueryTriggerInteraction.Ignore))
            {
                if (c.transform != plates[i]) pressed[i] = true;
            }
            if (pressed[i]) count++;

            plates[i].position = platePositions[i] + (pressed[i] ? Vector3.down * 0.08f : Vector3.zero);
            plates[i].GetComponent<Renderer>().material.color = pressed[i] ? new Color(0.3f, 0.9f, 0.4f) : new Color(0.85f, 0.3f, 0.25f);
        }

        AllPressed = count == plates.Length;
        status.text = "Plates: " + count + "/" + plates.Length;
        Vector3 target = AllPressed ? closedPosition + openOffset : closedPosition;
        transform.position = Vector3.MoveTowards(transform.position, target, openSpeed * Time.deltaTime);
    }

    private void BuildLabel()
    {
        UIDocument doc = gameObject.AddComponent<UIDocument>();
        PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
        settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
        settings.referenceResolution = new Vector2Int(1920, 1080);
        doc.panelSettings = settings;
        doc.rootVisualElement.pickingMode = PickingMode.Ignore;
        status = new Label();
        status.style.position = Position.Absolute;
        status.style.top = 30;
        status.style.left = 30;
        status.style.fontSize = 32;
        status.style.color = Color.white;
        doc.rootVisualElement.Add(status);
    }
}
```

Each plate polls for something standing on it instead of waiting for trigger events, so releasing a plate is detected as reliably as pressing it and a CharacterController counts like any other collider. The gate target is "up" only while all plates are down in the same frame, which makes the puzzle need three simultaneous weights (the player plus crates, or friends). Place the gate and adjust the offsets so the plates sit on your floor.

**Plan**
- `CollapsingTile` goes on any floor tile with a collider; each frame it checks with an `OverlapBox` just above its top face whether anything is standing on it.
- Once triggered a coroutine shakes the tile for 0.5 s, turns the collider off and lets it fall with increasing speed, and puts it back at its start position with the collider restored 4 s after the trigger.
- A `busy` flag prevents retriggering, and `OnCollapsed` / `OnRestored` events are available for sound or particles.

```csharp
using System;
using System.Collections;
using UnityEngine;

public class CollapsingTile : MonoBehaviour
{
    [SerializeField] private float shakeDuration = 0.5f;
    [SerializeField] private float shakeAmount = 0.06f;
    [SerializeField] private float respawnDelay = 4f;
    [SerializeField] private float gravity = 25f;

    private Vector3 home;
    private Collider tileCollider;
    private bool busy;

    public event Action OnCollapsed;
    public event Action OnRestored;

    private void Awake()
    {
        home = transform.position;
        tileCollider = GetComponent<Collider>();
    }

    private void Update()
    {
        if (!busy && IsOccupied()) StartCoroutine(Collapse());
    }

    private bool IsOccupied()
    {
        Bounds b = tileCollider.bounds;
        Vector3 center = new Vector3(b.center.x, b.max.y + 0.15f, b.center.z);
        Vector3 half = new Vector3(b.extents.x * 0.9f, 0.2f, b.extents.z * 0.9f);
        foreach (Collider c in Physics.OverlapBox(center, half, Quaternion.identity, ~0, QueryTriggerInteraction.Ignore))
        {
            if (c != tileCollider && !c.transform.IsChildOf(transform)) return true;
        }
        return false;
    }

    private IEnumerator Collapse()
    {
        busy = true;
        float elapsed = 0f;
        while (elapsed < shakeDuration)
        {
            transform.position = home + UnityEngine.Random.insideUnitSphere * shakeAmount;
            elapsed += Time.deltaTime;
            yield return null;
        }

        transform.position = home;
        tileCollider.enabled = false;
        if (OnCollapsed != null) OnCollapsed();

        float fallSpeed = 0f;
        while (elapsed < respawnDelay)
        {
            fallSpeed += gravity * Time.deltaTime;
            transform.position += Vector3.down * fallSpeed * Time.deltaTime;
            elapsed += Time.deltaTime;
            yield return null;
        }

        transform.position = home;
        tileCollider.enabled = true;
        busy = false;
        if (OnRestored != null) OnRestored();
    }
}
```

The occupancy test samples a box slightly above the tile's top face and shrunk to 90% of its footprint, so walking along the side of a tile or standing on a neighbour does not trigger it. Timings are measured from the moment of triggering: 0.5 s of shaking, then the fall, then a reset exactly 4 s after the first touch. Put the script on every tile (or on a tile prefab); each tile runs its own independent cycle.

**Plan**
- A trigger collider with this script detects the `Player`; it computes the new unlocked-level count from the current scene's build index and stores the larger of the old and new values in PlayerPrefs.
- A UI Toolkit "Level Complete!" banner appears, and after a short delay the next build index is loaded asynchronously, or the menu scene when it was the last level.
- `LevelCompleteTrigger.GetUnlockedLevels()` is a static helper for a level-select screen.

```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

[RequireComponent(typeof(Collider))]
public class LevelCompleteTrigger : MonoBehaviour
{
    public const string UnlockedKey = "Levels.Unlocked";

    [SerializeField] private int firstLevelBuildIndex = 1;
    [SerializeField] private int menuBuildIndex = 0;
    [SerializeField] private float loadDelay = 1.5f;

    private bool triggered;

    public static int GetUnlockedLevels()
    {
        return PlayerPrefs.GetInt(UnlockedKey, 1);
    }

    private void Reset()
    {
        GetComponent<Collider>().isTrigger = true;
    }

    private void OnTriggerEnter(Collider other)
    {
        if (triggered || !other.CompareTag("Player")) return;
        triggered = true;

        int current = SceneManager.GetActiveScene().buildIndex;
        int totalLevels = Mathf.Max(1, SceneManager.sceneCountInBuildSettings - firstLevelBuildIndex);
        int unlocked = Mathf.Max(GetUnlockedLevels(), current - firstLevelBuildIndex + 2);
        PlayerPrefs.SetInt(UnlockedKey, Mathf.Min(unlocked, totalLevels));
        PlayerPrefs.Save();

        ShowBanner(current + 1 < SceneManager.sceneCountInBuildSettings ? "Level Complete!" : "You finished the game!");
        int next = current + 1 < SceneManager.sceneCountInBuildSettings ? current + 1 : menuBuildIndex;
        StartCoroutine(LoadAfterDelay(next));
    }

    private IEnumerator LoadAfterDelay(int buildIndex)
    {
        yield return new WaitForSeconds(loadDelay);
        AsyncOperation operation = SceneManager.LoadSceneAsync(buildIndex);
        while (!operation.isDone) yield return null;
    }

    private void ShowBanner(string text)
    {
        UIDocument doc = gameObject.AddComponent<UIDocument>();
        PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
        settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
        settings.referenceResolution = new Vector2Int(1920, 1080);
        doc.panelSettings = settings;
        VisualElement root = doc.rootVisualElement;
        root.pickingMode = PickingMode.Ignore;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        Label banner = new Label(text);
        banner.style.fontSize = 72;
        banner.style.color = new Color(1f, 0.9f, 0.3f);
        root.Add(banner);
    }
}
```

Scenes must be added to Build Settings: with the default `firstLevelBuildIndex = 1` and a menu at index 0, finishing the scene at index 1 unlocks 2 levels, and finishing a later level never lowers an already higher count. The `triggered` flag stops multiple colliders on the player from firing the sequence twice, and the player object needs the built-in `Player` tag plus a Rigidbody or CharacterController so trigger events are generated.

**Plan**
- A `ProjectileTrap` fires a small sphere along `transform.forward` every `fireInterval` seconds; projectiles come from a pool (a `Queue`) so none are created or destroyed while firing.
- Each projectile is advanced by the script and, every frame, a `SphereCast` over the distance it will travel finds hits (ignoring the trap itself and triggers).
- On a hit the projectile is returned to the pool; if the thing hit is tagged `Player`, `TakeDamage(damage)` is sent to it (via `SendMessage`, ignored if there is no receiver).

```csharp
using System.Collections.Generic;
using UnityEngine;

public class ProjectileTrap : MonoBehaviour
{
    [SerializeField] private float fireInterval = 1.5f;
    [SerializeField] private float projectileSpeed = 14f;
    [SerializeField] private float projectileRadius = 0.25f;
    [SerializeField] private float lifetime = 4f;
    [SerializeField] private float damage = 10f;
    [SerializeField] private float startDelay = 0.5f;

    private class Shot
    {
        public Transform body;
        public float age;
        public Vector3 direction;
    }

    private readonly List<Shot> flying = new List<Shot>();
    private readonly Queue<Transform> pool = new Queue<Transform>();
    private float nextFire;

    private void Start()
    {
        nextFire = Time.time + startDelay;
    }

    private void Update()
    {
        if (Time.time >= nextFire)
        {
            nextFire = Time.time + fireInterval;
            Fire();
        }
        for (int i = flying.Count - 1; i >= 0; i--)
        {
            if (Advance(flying[i])) continue;
            Recycle(flying[i]);
            flying.RemoveAt(i);
        }
    }

    private void Fire()
    {
        Transform body = pool.Count > 0 ? pool.Dequeue() : CreateProjectile();
        body.position = transform.position + transform.forward * 0.8f;
        body.gameObject.SetActive(true);
        flying.Add(new Shot { body = body, age = 0f, direction = transform.forward });
    }

    // Returns true while the projectile should keep flying.
    private bool Advance(Shot shot)
    {
        shot.age += Time.deltaTime;
        float step = projectileSpeed * Time.deltaTime;
        RaycastHit hit;
        if (Physics.SphereCast(shot.body.position, projectileRadius, shot.direction, out hit, step, ~0, QueryTriggerInteraction.Ignore)
            && !hit.transform.IsChildOf(transform))
        {
            if (hit.collider.CompareTag("Player"))
                hit.collider.SendMessage("TakeDamage", damage, SendMessageOptions.DontRequireReceiver);
            return false;
        }
        shot.body.position += shot.direction * step;
        return shot.age < lifetime;
    }

    private Transform CreateProjectile()
    {
        GameObject sphere = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        sphere.name = "TrapProjectile";
        sphere.transform.localScale = Vector3.one * projectileRadius * 2f;
        sphere.GetComponent<Renderer>().material.color = new Color(1f, 0.35f, 0.1f);
        Destroy(sphere.GetComponent<Collider>());
        return sphere.transform;
    }

    private void Recycle(Shot shot)
    {
        shot.body.gameObject.SetActive(false);
        pool.Enqueue(shot.body);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.red;
        Gizmos.DrawRay(transform.position, transform.forward * 5f);
    }
}
```

The trap needs no prefab: it builds its projectiles, pools them and fires along its own forward axis, so rotating the trap in the scene aims it. Moving the sphere by hand and casting over the exact distance travelled each frame means fast projectiles cannot tunnel through thin walls, and the player only needs a method called `TakeDamage(float)` on any component of the object that has the Player tag.

**Plan**
- A lever component with a handle: when the player is within reach, pressing E flips a boolean `extended` and shows a UI Toolkit hint.
- A `progress` value (0-1) moves toward 0 or 1 at `1 / duration` per second and is passed through `Mathf.SmoothStep` for ease in and out; the same value tilts the lever handle between -40 and +40 degrees.
- The bridge is a cube whose Z scale grows from its fixed near end, and its collider is only enabled once it is more than 5% extended; a default bridge and handle are created if none are assigned.

```csharp
using UnityEngine;
using UnityEngine.UIElements;

public class LeverBridge : MonoBehaviour
{
    [SerializeField] private Transform player;
    [SerializeField] private Transform bridge;
    [SerializeField] private Transform handle;
    [SerializeField] private Vector3 bridgeStart = new Vector3(0f, 0f, 3f);
    [SerializeField] private float bridgeLength = 12f;
    [SerializeField] private float bridgeWidth = 4f;
    [SerializeField] private float duration = 1.5f;
    [SerializeField] private float reach = 2.5f;
    [SerializeField] private KeyCode useKey = KeyCode.E;

    private bool extended;
    private float progress;
    private Collider bridgeCollider;
    private Label hint;

    public bool Extended { get { return extended; } }

    private void Start()
    {
        if (player == null && Camera.main != null) player = Camera.main.transform;
        if (bridge == null)
        {
            GameObject cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
            cube.name = "Bridge";
            cube.GetComponent<Renderer>().material.color = new Color(0.55f, 0.4f, 0.25f);
            bridge = cube.transform;
        }
        if (handle == null)
        {
            GameObject stick = GameObject.CreatePrimitive(PrimitiveType.Cube);
            stick.name = "LeverHandle";
            stick.transform.SetParent(transform, false);
            stick.transform.localScale = new Vector3(0.15f, 1.2f, 0.15f);
            stick.GetComponent<Renderer>().material.color = new Color(0.9f, 0.2f, 0.2f);
            Destroy(stick.GetComponent<Collider>());
            handle = stick.transform;
        }
        bridgeCollider = bridge.GetComponent<Collider>();
        BuildHint();
        ApplyPose();
    }

    private void Update()
    {
        bool near = player != null && Vector3.Distance(player.position, transform.position) <= reach;
        hint.style.display = near ? DisplayStyle.Flex : DisplayStyle.None;
        if (near && Input.GetKeyDown(useKey)) extended = !extended;

        float target = extended ? 1f : 0f;
        progress = Mathf.MoveTowards(progress, target, Time.deltaTime / duration);
        ApplyPose();
    }

    private void ApplyPose()
    {
        float eased = Mathf.SmoothStep(0f, 1f, progress);
        float length = Mathf.Max(0.01f, bridgeLength * eased);
        bridge.localScale = new Vector3(bridgeWidth, 0.4f, length);
        bridge.position = bridgeStart + Vector3.forward * (length / 2f);
        if (bridgeCollider != null) bridgeCollider.enabled = eased > 0.05f;
        handle.localRotation = Quaternion.Euler(Mathf.Lerp(-40f, 40f, eased), 0f, 0f);
        handle.localPosition = handle.localRotation * new Vector3(0f, 0.6f, 0f);
    }

    private void BuildHint()
    {
        UIDocument doc = gameObject.AddComponent<UIDocument>();
        PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
        settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
        settings.referenceResolution = new Vector2Int(1920, 1080);
        doc.panelSettings = settings;
        doc.rootVisualElement.pickingMode = PickingMode.Ignore;
        hint = new Label("Press " + useKey + " to use the lever");
        hint.style.position = Position.Absolute;
        hint.style.bottom = 140;
        hint.style.alignSelf = Align.Center;
        hint.style.fontSize = 32;
        hint.style.color = Color.white;
        hint.style.display = DisplayStyle.None;
        doc.rootVisualElement.Add(hint);
    }
}
```

The animation is driven by a single `progress` number, which makes it reversible at any moment: pulling the lever again mid-way simply starts moving it back from where it is, with no jump. Scaling the bridge about its near end (its centre is moved half the current length forward) makes it look like it slides out of the cliff, and the collider only turns on once there is something to stand on.

